package com.agentpowflow.controlplane.integrations;

import com.agentpowflow.controlplane.knowledge.KnowledgeExecutionProperties;
import com.agentpowflow.controlplane.runs.InternalApiProperties;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientResponseException;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Duration; import java.util.*;

@Service
public class JavaScriptToolService {
 private final JavaScriptToolRepository tools; private final JavaScriptToolVersionRepository versions; private final ObjectMapper json; private final RestClient execution; private final String executionBase; private final String internalToken;
 public JavaScriptToolService(JavaScriptToolRepository t,JavaScriptToolVersionRepository v,ObjectMapper j,KnowledgeExecutionProperties p,InternalApiProperties i){tools=t;versions=v;json=j;execution=RestClient.builder().build();executionBase=p.getExecutionBaseUrl();internalToken=i.getToken();}
 @Transactional(readOnly=true) public List<ToolView> list(String tenant,String actor){return tools.findByTenantIdAndCreatedByOrderByUpdatedAtDesc(tenant,actor).stream().map(this::view).toList();}
 @Transactional public ToolView save(String tenant,String actor,String id,ToolInput in){validate(in);JavaScriptToolEntity e=id==null?new JavaScriptToolEntity():owned(id,tenant,actor);e.setTenantId(tenant);e.setName(in.name().trim());e.setDescription(safe(in.description()));e.setDraftDefinitionJson(write(definition(in)));if(id==null)e.setCreatedBy(actor);e.setUpdatedBy(actor);return view(tools.save(e));}
 @Transactional public ToolView publish(String tenant,String actor,String id){JavaScriptToolEntity e=owned(id,tenant,actor);JsonNode d=read(e.getDraftDefinitionJson());if(!d.path("allow_agent").asBoolean()&&!d.path("allow_workflow").asBoolean())throw bad("至少分配一个使用范围后才能发布");int no=e.getLatestVersionNo()+1;JavaScriptToolVersionEntity v=new JavaScriptToolVersionEntity();v.setToolId(id);v.setTenantId(tenant);v.setVersionNo(no);v.setDefinitionJson(e.getDraftDefinitionJson());v.setChecksum(sha(e.getDraftDefinitionJson()));v.setPublishedBy(actor);versions.save(v);e.setLatestVersionNo(no);e.setStatus("PUBLISHED");e.setUpdatedBy(actor);return view(tools.save(e));}
 @Transactional(readOnly=true) public JsonNode executeDraft(String tenant,String actor,String id,JsonNode arguments){JavaScriptToolEntity e=owned(id,tenant,actor);return execute(tenant,actor,id,0,read(e.getDraftDefinitionJson()),arguments);}
 @Transactional(readOnly=true) public JsonNode executePublished(String tenant,String actor,String id,int version,JsonNode arguments,String scope){JavaScriptToolEntity e=owned(id,tenant,actor);JavaScriptToolVersionEntity v=versions.findByToolIdAndTenantIdAndVersionNo(id,tenant,version).orElseThrow(()->notFound("tool version"));JsonNode d=read(v.getDefinitionJson());String key="WORKFLOW".equalsIgnoreCase(scope)?"allow_workflow":"allow_agent";if(!d.path(key).asBoolean())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"工具未授权给该使用范围");return execute(tenant,actor,id,version,d,arguments);}
 @Transactional(readOnly=true) public ToolView resolveOwned(String t,String a,String id){return view(owned(id,t,a));}
 @Transactional(readOnly=true) public JsonNode resolveVersion(String t,String id,int version){return versions.findByToolIdAndTenantIdAndVersionNo(id,t,version).map(v->read(v.getDefinitionJson())).orElseThrow(()->notFound("tool version"));}
 @Transactional public void delete(String t,String a,String id){tools.delete(owned(id,t,a));}
 private JsonNode execute(String tenant,String actor,String id,int version,JsonNode definition,JsonNode args){try{return execution.post().uri(executionBase+"/api/v1/internal/javascript-tools/execute").header("X-Internal-Token",internalToken).body(Map.of("tenant_id",tenant,"actor_id",actor,"tool_id",id,"tool_version",version,"definition",definition,"arguments",args==null?json.createObjectNode():args)).retrieve().body(JsonNode.class);}catch(RestClientResponseException e){String detail="工具执行失败";try{detail=json.readTree(e.getResponseBodyAsString()).path("detail").asText(detail);}catch(Exception ignored){}throw new ResponseStatusException(e.getStatusCode(),detail,e);}catch(RuntimeException e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"工具执行服务暂时不可用",e);}}
 private ObjectNode definition(ToolInput in){ObjectNode d=json.createObjectNode();d.put("code",in.code().trim());d.set("input_schema",schema(in.input_schema()));d.set("output_schema",schema(in.output_schema()));d.put("allow_agent",Boolean.TRUE.equals(in.allow_agent()));d.put("allow_workflow",Boolean.TRUE.equals(in.allow_workflow()));d.put("risk_level",normRisk(in.risk_level()));d.put("timeout_ms",bound(in.timeout_ms(),1000,10,5000));d.put("memory_mb",bound(in.memory_mb(),16,4,64));return d;}
 private void validate(ToolInput in){if(in==null||blank(in.name())||blank(in.code()))throw bad("名称和 JavaScript 函数不能为空");if(in.name().trim().length()>128||in.code().length()>30000)throw bad("工具内容超出限制");if(in.code().matches("(?s).*\\b(fetch|XMLHttpRequest|WebSocket|require|process|Deno)\\b.*"))throw bad("JavaScript 工具不能直接访问网络、文件或进程，请组合 MCP/HTTP 工具");}
 private ToolView view(JavaScriptToolEntity e){JsonNode latest=e.getLatestVersionNo()>0?versions.findByToolIdAndTenantIdAndVersionNo(e.getToolId(),e.getTenantId(),e.getLatestVersionNo()).map(v->read(v.getDefinitionJson())).orElse(null):null;return new ToolView(e.getToolId(),e.getName(),e.getDescription(),e.getStatus(),e.getLatestVersionNo(),read(e.getDraftDefinitionJson()),latest,e.getRowVersion(),e.getUpdatedAt());}
 private JavaScriptToolEntity owned(String id,String t,String a){return tools.findByToolIdAndTenantIdAndCreatedBy(id,t,a).orElseThrow(()->notFound("tool"));}
 private JsonNode schema(JsonNode n){return n==null||!n.isObject()?json.createObjectNode().put("type","object"):n;} private int bound(Integer v,int d,int min,int max){return Math.max(min,Math.min(v==null?d:v,max));} private String normRisk(String v){String n=safe(v).toUpperCase();return Set.of("READ_ONLY","COMPUTE","WRITE").contains(n)?n:"COMPUTE";}
 private JsonNode read(String s){try{return json.readTree(s);}catch(Exception e){return json.createObjectNode();}} private String write(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}} private String sha(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private static String safe(String v){return v==null?"":v.trim();} private static boolean blank(String v){return v==null||v.isBlank();} private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);} private static ResponseStatusException notFound(String n){return new ResponseStatusException(HttpStatus.NOT_FOUND,n+" not found");}
 public record ToolInput(String name,String description,String code,JsonNode input_schema,JsonNode output_schema,Boolean allow_agent,Boolean allow_workflow,String risk_level,Integer timeout_ms,Integer memory_mb){} public record ToolView(String tool_id,String name,String description,String status,int latest_version_no,JsonNode draft_definition,JsonNode latest_definition,long revision,java.time.Instant updated_at){}
}
